  "/**\n * 订单金额统计。\n * 注释与多余空白会被去掉，字符串 / 模板串 / 正则原样保留。\n */\nfunction summarize(orders) {\n  var total = 0;          // 累加金额\n  var re = /^https?:\\/\\//;   // 正则里的转义斜杠不能被当成分隔符\n\n  for (var i = 0; i < orders.length; i++) {\n    var order = orders[i];\n    if (re.test(order.url || \"http://placeholder.test\")) {\n      total += order.amount;\n    }\n    console.log(`订单 ${order.id} 金额 ${order.amount}，累计 ${total}`);\n  }\n\n  return {\n    total: total,\n    count: orders.length,\n  };\n}\n": "/**\n * Order amount statistics.\n * Comments and redundant whitespace will be removed, and strings/template strings/regulars will remain intact.\n */\nfunction summarize(orders) {\n  var total = 0; // Accumulated amount\n  var re = /^https?:\\/\\//; // Escaped slashes in regular expressions cannot be used as delimiters\n\n  for (var i = 0; i < orders.length; i++) {\n    var order = orders[i];\n    if (re.test(order.url || \"http://placeholder.test\")) {\n      total += order.amount;\n    }\n    console.log(`Order ${order.id} amount ${order.amount}, cumulative ${total}`);\n  }\n\n  return {\n    total: total,\n    count: orders.length,\n  };\n}",
